WITH exploded AS (SELECT id, host, log_ts, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS attr_key, attr_value) SELECT latency_ms, attr_key, attr_value, COUNT(status_code) OVER (PARTITION BY host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS status_code_count_1h, RANK() OVER (PARTITION BY host, attr_key ORDER BY latency_ms DESC) AS latency_ms_rank, RANK() OVER (PARTITION BY attr_key ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_rank_2, AVG(latency_ms) OVER (PARTITION BY YEAR(log_ts), host) AS log_ts_year_avg_latency_ms FROM exploded;
